import{_ as t,o as i,c as h,a5 as l}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-5-user-management-verifydisabledelete/report3_spec.md","filePath":"feature/admin-management/3-10-5-user-management-verifydisabledelete/report3_spec.md"}'),g={name:"feature/admin-management/3-10-5-user-management-verifydisabledelete/report3_spec.md"};function c(o,n,u,r,e,a){return i(),h("div",null,[...n[0]||(n[0]=[l("<p><strong>3.10.5 User Management (Quản lý Trạng thái và Strike)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) chọn thao tác &quot;Quản lý Trạng thái &amp; Vi phạm&quot; từ danh sách người dùng (/admin/users).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN quản lý tuân thủ. Người dùng tự xác thực email qua luồng kích hoạt.</li><li><strong>Purpose</strong>: Quản lý strike YELLOW/ORANGE/RED và cờ tài khoản. PENDING_VERIFICATION nghĩa là chưa xác thực email; chức năng này không khôi phục Authenticator bị mất.</li><li><strong>Interface</strong>: Hộp thoại Quản lý Trạng thái &amp; Thẻ phạt Vi phạm (SCR-ADM-05), hiển thị dưới dạng modal gồm thông tin tài khoản, bộ đếm thẻ phạt 3 cấp độ và các nút hành động.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN và đối tượng, lưu sự kiện strike và audit, mỗi nhóm vàng chỉ quy đổi một lần, cập nhật hạn thời gian sạch và hạn chế đăng bài, tạo một yêu cầu xử phạt chờ cho RED/ba ORANGE còn hiệu lực. Gỡ theo strikeId cụ thể, không gỡ dây chuyền.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Hộp thoại Quản lý Trạng thái &amp; Thẻ phạt Vi phạm Người dùng (SCR-ADM-05):</p><ul><li>Left/Header: Tiêu đề &quot;Quản lý Trạng thái &amp; Thẻ phạt Vi phạm&quot;, biểu tượng bảo vệ, và nhãn trạng thái hiện tại (ACTIVE xanh lá, FLAGGED vàng cam, PENDING_VERIFICATION vàng chanh).</li><li>Center: Hồ sơ, trạng thái và tình trạng xác thực email; YELLOW chưa quy đổi x/3, ORANGE còn hiệu lực x/3, chỉ báo RED, lịch sử đã quy đổi/hết hạn/gỡ và hạn thời gian sạch. Thao tác: ghi strike, gỡ đúng thẻ, bỏ cờ sau khi xử lý thẻ còn hiệu lực. Link yêu cầu xử phạt chờ duyệt; không có Verify 2FA.</li><li>Buttons: Hủy, Xác nhận ghi strike / Gỡ thẻ / Bỏ cờ, Mở yêu cầu xử phạt.</li><li>Footer: Ghi chú kiểm toán: &quot;Mọi thao tác ghi nhận hoặc gỡ bỏ vi phạm đều được lưu vĩnh viễn trong Audit Log kèm mã Admin và lý do bắt buộc. Hệ thống tuyệt đối không xóa tài khoản người dùng&quot;.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: userId, action (add_strike, remove_strike, unflag), reason; add_strike cần violationLevel (YELLOW/ORANGE/RED) và violationCategory; remove_strike cần strikeId.</li><li><strong>Input optional</strong>: postId, contentVersionId, tham chiếu chứng cứ.</li><li><strong>System data</strong>: adminId, status, emailVerifiedAt, requirePasswordReset, lastViolationAt, cleanPeriodEndsAt, trạng thái thẻ và liên kết quy đổi, bộ đếm còn hiệu lực, pendingSanctionRequestId.</li><li><strong>Output</strong>: Kết quả cập nhật hồ sơ người dùng kèm mã HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-63</strong>: Chỉ ADMIN ghi/gỡ strike và quản lý cờ, bắt buộc lý do và audit bất biến.</li><li><strong>BR-92</strong>: Admin không xóa cứng user; giữ dữ liệu liên quan và lịch sử thẻ. Người dùng tự xóa tài khoản là luồng riêng.</li><li><strong>BR-15</strong>: PENDING_VERIFICATION là chưa xác thực email. User tự xác thực; Admin không bỏ qua hoặc reset TOTP tại đây. Xác thực email không bắt buộc thiết lập lại 2FA.</li><li><strong>BR-94</strong>: YELLOW là cảnh cáo. Có ORANGE còn hiệu lực thì tài khoản bị FLAGGED, đăng bài phải được ADMIN duyệt nhưng vẫn được đăng nhập. RED hoặc đủ ba ORANGE còn hiệu lực tạo yêu cầu xem xét xử phạt tại FR 3.10.9; chỉ khóa sau khi Admin xác nhận.</li><li><strong>BR-95</strong>: Ba YELLOW còn hiệu lực, chưa quy đổi, thuộc bất kỳ loại lỗi nào tạo một ORANGE độc lập. Đánh dấu cả ba thẻ nguồn đã quy đổi và giữ liên kết. YELLOW thứ tư bắt đầu nhóm tiếp theo; sáu YELLOW hợp lệ tạo hai ORANGE. Có thể ghi nhận ORANGE trực tiếp. Gỡ YELLOW nguồn không tự gỡ ORANGE phát sinh.</li><li><strong>BR-96</strong>: Mỗi vi phạm mới bắt đầu lại thời gian 30 ngày liên tiếp không vi phạm cho tài khoản. Các thẻ còn hiệu lực hết hạn sau thời gian sạch này, không tính riêng 30 ngày từ lúc tạo từng thẻ. Không hồi sinh thẻ đã hết hạn/đã gỡ; quy đổi không phải một lần tái phạm mới. Giữ lịch sử bất biến khi hết hạn hoặc gỡ. Hết ORANGE chỉ khôi phục quyền đăng bài nếu không còn khóa tài khoản hoặc hạn chế kích hoạt.</li><li><strong>BR-23</strong>: Owner duy nhất của Agency/Workspace vẫn được sửa hồ sơ, ghi strike, gắn cờ và khóa tài khoản 30 ngày sau xác nhận. Thành viên khác tiếp tục quyền hiện có; thao tác chỉ Owner được làm tạm dừng đến khi mở khóa. Không khóa cả Agency, không tự chuyển quyền sở hữu. Quyền Owner độc lập với system role.</li><li><strong>BR-15</strong>: Unflag yêu cầu gỡ/đợi hết hạn các thẻ vi phạm còn hiệu lực trước, đặc biệt toàn bộ ORANGE. Không dùng unflag mở DEACTIVATED; FR 3.10.9 quản lý thời hạn khóa riêng 30 ngày.</li><li><strong>BR-35</strong>: Admin không tự xử phạt hoặc xử phạt ADMIN ngang hàng.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu quyền ADMIN hoặc tự phạt/phạt Admin ngang hàng → MSG39.</li><li>Không có user/thẻ → MSG38; thiếu lý do → MSG02.</li><li>Unflag khi còn thẻ vi phạm hiệu lực hoặc đối tượng DEACTIVATED → từ chối chuyển trạng thái.</li><li>Yêu cầu/quy đổi lặp → trả kết quả đã có, không tạo thẻ hoặc xử phạt trùng.</li><li>Thao tác hợp lệ với Owner duy nhất được phép; hiển thị ảnh hưởng Agency trước khóa.</li><li>Cập nhật thẻ/trạng thái thành công → MSG26.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin mở hộp thoại trạng thái/strike và xem thẻ còn hiệu lực cùng lịch sử.</li><li>Chọn thêm, gỡ theo strikeId hoặc unflag và nhập lý do.</li><li>Kiểm tra nguyên tử quyền, trạng thái đối tượng và điều kiện chuyển.</li><li>Ghi vi phạm; bắt đầu lại thời gian sạch cho thẻ còn hiệu lực. Quy đổi nhóm vàng hợp lệ đúng một lần hoặc chỉ gỡ thẻ đã chọn.</li><li>Tính lại FLAGGED và bộ đếm; RED/ba ORANGE mở yêu cầu xem xét mà chưa khóa.</li><li>Lưu audit, cập nhật UI. Job nền hết hạn thẻ sau 30 ngày sạch; không bỏ qua thời hạn khóa tài khoản.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Thiếu lý do → MSG02.</li><li>3.a1: Tự phạt/phạt Admin ngang hàng hoặc thiếu quyền ADMIN → MSG39.</li><li>3.a2: Chưa xác thực email phải dùng luồng kích hoạt của user; không có Admin verify-2FA để bỏ qua.</li><li>3.a3: Revision cũ/gỡ hoặc quy đổi đồng thời → tải trạng thái nhất quán; mỗi thao tác chỉ một kết quả audit.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Lưu vòng đời thẻ và liên kết quy đổi nguồn; giữ lịch sử.</li><li>User FLAGGED vẫn đăng nhập nhưng bài phải được ADMIN duyệt, kể cả bài đã lên lịch.</li><li>RED/ba ORANGE để lại yêu cầu chờ Admin xác nhận.</li><li>Kích hoạt email và thời hạn khóa DEACTIVATED độc lập với unflag/dọn thẻ.</li></ul>",14)])])}const m=t(g,[["render",c]]);export{p as __pageData,m as default};
